import { lstat, readFile, rename, rm } from "node:fs/promises";
import path from "node:path";
import { writeFileAtomic } from "@local/vibe64-core/server/atomicFile";
import { vibe64SharedModes } from "@local/vibe64-execution/server/hostProfile";

function sharedFileModes() {
  const modes = vibe64SharedModes();
  return { directoryMode: modes.inheritingDirectory, fileMode: modes.file };
}

const GENERATED_ENV_HEADER = [
  "# Generated by Vibe64 from the Genesis Stack.",
  "# Do not edit. Configure project values in Vibe64 Env."
].join("\n");

function dotenvValue(value = "") {
  const text = String(value ?? "");
  return text && /^[A-Za-z0-9_./:@+-]+$/u.test(text)
    ? text
    : JSON.stringify(text);
}

function generatedDotenv(environment = {}) {
  const assignments = Object.entries(environment)
    .filter(([key, value]) => /^[A-Za-z_][A-Za-z0-9_]*$/u.test(key) && typeof value === "string")
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([key, value]) => `${key}=${dotenvValue(value)}`);
  return `${GENERATED_ENV_HEADER}\n\n${assignments.join("\n")}${assignments.length ? "\n" : ""}`;
}

function generatedDotenvIsOwned(source = "") {
  return String(source || "").startsWith(`${GENERATED_ENV_HEADER}\n`);
}

async function optionalFile(filePath = "") {
  try {
    return await readFile(filePath, "utf8");
  } catch (error) {
    if (["ENOENT", "ENOTDIR"].includes(error?.code)) {
      return null;
    }
    throw error;
  }
}

async function assertProjectionPath(sourceRoot = "", relativePath = "", {
  label = "Environment file", code = "vibe64_environment_file"
} = {}) {
  const root = path.resolve(sourceRoot);
  const target = path.resolve(root, relativePath);
  if (!target.startsWith(`${root}${path.sep}`)) {
    const error = new Error(`${label} escapes the project source: ${relativePath}.`);
    error.code = `${code}_outside_source`;
    throw error;
  }
  let current = root;
  for (const part of relativePath.split("/")) {
    current = path.join(current, part);
    const entry = await lstat(current).catch((error) => {
      if (["ENOENT", "ENOTDIR"].includes(error?.code)) {
        return null;
      }
      throw error;
    });
    if (entry?.isSymbolicLink()) {
      const error = new Error(`${label} path contains a symbolic link: ${relativePath}.`);
      error.code = `${code}_symlink`;
      throw error;
    }
    if (!entry) {
      break;
    }
  }
  return target;
}

async function backupPath(filePath = "", now = new Date()) {
  const base = `${filePath}.vibe64-backup-${now.toISOString().replace(/[:.]/gu, "-")}`;
  for (let sequence = 0; ; sequence += 1) {
    const candidate = sequence === 0 ? base : `${base}-${sequence}`;
    const exists = await lstat(candidate).then(() => true).catch((error) => {
      if (["ENOENT", "ENOTDIR"].includes(error?.code)) {
        return false;
      }
      throw error;
    });
    if (!exists) {
      return candidate;
    }
  }
}

function gitExcludePattern(relativePath = "") {
  const normalizedPath = String(relativePath || "").replaceAll("\\", "/");
  return `/${[...normalizedPath]
    .map((character) => "\\ #!*?[]".includes(character) ? `\\${character}` : character)
    .join("")}`;
}

async function managedGitExcludeProjection(sourceRoot = "", relativePaths = [], {
  section = "environment", atomicJson = false
} = {}) {
  const beginMarker = `# BEGIN Vibe64 managed ${section} files`;
  const endMarker = `# END Vibe64 managed ${section} files`;
  const gitDirectory = path.join(path.resolve(sourceRoot), ".git");
  const gitEntry = await lstat(gitDirectory).catch((error) => {
    if (["ENOENT", "ENOTDIR"].includes(error?.code)) {
      return null;
    }
    throw error;
  });
  if (!gitEntry?.isDirectory()) {
    const error = new Error("Project environment files require an ordinary local Git directory.");
    error.code = "vibe64_environment_git_directory_required";
    throw error;
  }

  const infoDirectory = path.join(gitDirectory, "info");
  const excludePath = path.join(infoDirectory, "exclude");
  for (const entryPath of [infoDirectory, excludePath]) {
    const entry = await lstat(entryPath).catch((error) => {
      if (["ENOENT", "ENOTDIR"].includes(error?.code)) {
        return null;
      }
      throw error;
    });
    if (entry?.isSymbolicLink()) {
      const error = new Error("The repository's local Git exclude path contains a symbolic link.");
      error.code = "vibe64_environment_git_exclude_symlink";
      throw error;
    }
  }

  const existing = await optionalFile(excludePath) || "";
  const lines = existing.replace(/\r\n?/gu, "\n").split("\n");
  const begin = lines.indexOf(beginMarker);
  const end = lines.indexOf(endMarker);
  if ((begin >= 0) !== (end >= 0) || (begin >= 0 && end < begin)) {
    const error = new Error("The repository's managed environment exclude block is invalid.");
    error.code = "vibe64_environment_git_exclude_invalid";
    throw error;
  }
  const preserved = begin >= 0
    ? [...lines.slice(0, begin), ...lines.slice(end + 1)]
    : lines;
  while (preserved.at(-1) === "") {
    preserved.pop();
  }
  const patterns = [...new Set(relativePaths.flatMap((relativePath) => [
    gitExcludePattern(relativePath),
    `${gitExcludePattern(relativePath)}.vibe64-backup-*`,
    ...(atomicJson ? [`${gitExcludePattern(path.posix.join(path.posix.dirname(relativePath), `.${path.posix.basename(relativePath)}`))}.*.tmp`] : [])
  ]))].sort();
  const expected = [
    ...preserved,
    ...(preserved.length > 0 ? [""] : []),
    beginMarker,
    ...patterns,
    endMarker,
    ""
  ].join("\n");
  return { excludePath, existing, expected };
}

async function writeManagedGitExcludes(sourceRoot = "", relativePaths = [], options = {}) {
  const { excludePath, existing, expected } = await managedGitExcludeProjection(
    sourceRoot, relativePaths, options
  );
  if (existing === expected) {
    return;
  }

  await writeFileAtomic(excludePath, expected, sharedFileModes());
}

async function writeGeneratedDotenv({
  environment = {},
  now = new Date(),
  relativePath = "",
  sourceRoot = ""
} = {}) {
  const filePath = await assertProjectionPath(sourceRoot, relativePath);
  const expected = generatedDotenv(environment);
  const existing = await optionalFile(filePath);
  let preservedPath = "";
  if (existing !== null && !generatedDotenvIsOwned(existing)) {
    preservedPath = await backupPath(filePath, now);
    await rename(filePath, preservedPath);
  }
  if (existing === expected && !preservedPath) {
    return {
      changed: false,
      format: "dotenv",
      path: relativePath,
      preservedPath: ""
    };
  }
  try {
    await writeFileAtomic(filePath, expected, sharedFileModes());
  } catch (error) {
    if (preservedPath) {
      await rm(filePath, {
        force: true
      }).catch(() => null);
      await rename(preservedPath, filePath).catch(() => null);
    }
    throw error;
  }
  return {
    changed: true,
    format: "dotenv",
    path: relativePath,
    preservedPath
  };
}

function environmentFilePaths(files = []) {
  return files.map((file) => {
    if (file?.format !== "dotenv") {
      const error = new Error(`Unsupported project environment file format: ${file?.format || "(empty)"}.`);
      error.code = "vibe64_environment_file_format_unsupported";
      throw error;
    }
    return String(file.path || "");
  });
}

async function projectEnvironmentFilesAreCurrent({
  environment = {},
  files = [],
  sourceRoot = ""
} = {}) {
  if (!sourceRoot || !Array.isArray(files) || files.length === 0) {
    return true;
  }
  const relativePaths = environmentFilePaths(files);
  const paths = await Promise.all(relativePaths.map((relativePath) => assertProjectionPath(sourceRoot, relativePath)));
  const { existing, expected } = await managedGitExcludeProjection(sourceRoot, relativePaths);
  if (existing !== expected) {
    return false;
  }
  const dotenv = generatedDotenv(environment);
  for (const filePath of paths) {
    if (await optionalFile(filePath) !== dotenv) {
      return false;
    }
  }
  return true;
}

async function materializeProjectEnvironmentFiles({
  environment = {},
  files = [],
  now = new Date(),
  sourceRoot = ""
} = {}) {
  if (!sourceRoot || !Array.isArray(files) || files.length === 0) {
    return [];
  }
  const relativePaths = environmentFilePaths(files);
  await Promise.all(relativePaths.map((relativePath) => assertProjectionPath(sourceRoot, relativePath)));
  await writeManagedGitExcludes(sourceRoot, relativePaths);
  const results = [];
  for (const relativePath of relativePaths) {
    results.push(await writeGeneratedDotenv({
      environment,
      now,
      relativePath,
      sourceRoot
    }));
  }
  return results;
}

export {
  assertProjectionPath,
  GENERATED_ENV_HEADER,
  generatedDotenv,
  generatedDotenvIsOwned,
  materializeProjectEnvironmentFiles,
  projectEnvironmentFilesAreCurrent,
  writeManagedGitExcludes
};
